// Community content keeps its own license; imported personal decks stay local.
export function enabledQuestions(questions,state){return questions.filter(q=>!q.origin||state.enabledPacks.includes(q.origin));}
export function personalCards(state){return state.personalDecks.flatMap(deck=>deck.enabled?deck.cards.map(card=>({...card,personal:true,deckId:deck.id,deckName:deck.name,domain:0})):[]);}
export function allPersonalCards(state){return state.personalDecks.flatMap(deck=>deck.cards.map(card=>({...card,personal:true,deckId:deck.id,deckName:deck.name,domain:0})));}
export function validateDecks(value){if(value===undefined)return [];if(!Array.isArray(value)||value.length>50)throw new Error('Invalid personal decks.');const ids=new Set();let total=0;return value.map(d=>{if(!d||!/^personal-[a-f0-9]{64}$/.test(d.id)||ids.has(d.id)||typeof d.name!=='string'||!d.name.trim()||d.name.length>200||typeof d.enabled!=='boolean'||!Array.isArray(d.cards)||!d.cards.length)throw new Error('Invalid personal deck.');ids.add(d.id);const cardIds=new Set();const cards=d.cards.map(c=>{if(!c||typeof c.id!=='string'||!c.id.startsWith(d.id+'-')||c.id.length>150||cardIds.has(c.id)||typeof c.front!=='string'||typeof c.answer!=='string'||!c.front.trim()||!c.answer.trim()||c.front.length>20000||c.answer.length>20000)throw new Error('Invalid imported card.');cardIds.add(c.id);if(++total>10000)throw new Error('Maximum 10,000 personal cards.');return {id:c.id,front:c.front,answer:c.answer};});return {id:d.id,name:d.name,enabled:d.enabled,cards};});}
